# The pattern works for i values directly, not modulo
# Col 0 gets marked when i in {0, 1, 4}
# Col 1 gets marked when i in {0, 4, 5}
# Col 2 gets marked when i in {0}

# So i is checked directly, not i % 8

def transform_original_grid(grid):
    """Transform using the direct i-based column pattern rule."""
    h, w = len(grid), len(grid[0])
    all_vals = [x for row in grid for x in row if x != 0]
    primary = max(set(all_vals), key=lambda x: all_vals.count(x))

    # For each column j, which row indices i get marked?
    COLS_MARKED = {
        0: {0, 1, 4},  
        1: {0, 4, 5},  
        2: {0},        
    }

    output = [[0] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == primary and j in COLS_MARKED.get(i, set()):
                output[i][j] = 2

    return output, primary

result, primary = transform_original_grid(demo_input)
print(f"Demo output with direct i-based pattern:")
for row in result:
    print(f"  {row}")

print(f"\nDoes it match expected? {result == demo_output}")

# Now let me apply this to the test input (primary=8, 19 rows)
for i in range(19):
