# Fix the list comprehension issue
def transform_pairwise(grid, primary):
    h, w = len(grid), len(grid[0])
    out_h = (h + 1) // 2  # ceiling division
    output = [[0] for _ in range(out_h)]
    for i in range(out_h):
        output[i] = [0] * w  # Create list with right length

    for i in range(out_h):
        start_row = 2 * i
        if start_row + 1 >= h:
            for j in range(w):
                if grid[start_row][j] == primary:
                    output[i][j] = 2
        else:
            for j in range(w):
                if grid[start_row][j] == primary and grid[start_row+1][j] == primary:
                    output[i][j] = 2

    return output

# Test the AND version on demo
result_and = transform_pairwise(demo_input, 5)
print("AND version on demo:")
for row in result_and[:6]:
    print(f"  {row}")

# Test the OR version on demo
def transform_pairwise_or(grid, primary):
    h, w = len(grid), len(grid[0])
    out_h = (h + 1) // 2
    output = [[0] for _ in range(out_h)]
    for i in range(out_h):
        output[i] = [0] * w

    for i in range(out_h):
        start_row = 2 * i
        for j in range(w):
            if grid[start_row][j] == primary or (start_row + 1 < h and grid[start_row+1][j] == primary):
                output[i][j] = 2

    return output

